INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Sind variable Kosten abhängig von der Produktionsmenge?', 2, '[{"text": "Ja", "correct": true, "because": "Variable Kosten ändern sich mit der Menge"}, {"text": "Nein", "correct": false, "because": "Definition der variablen Kosten"}]'),
('00000000-0000-0000-0000-000000000000', 'Bleiben variable Kosten bei sinkender Produktion gleich?', 2, '[{"text": "Ja", "correct": false, "because": "Sie sinken mit der Produktionsmenge"}, {"text": "Nein", "correct": true, "because": "Variable Kosten sind mengenabhängig"}]'),
('00000000-0000-0000-0000-000000000000', 'Zählen Materialkosten zu den variablen Kosten?', 2, '[{"text": "Ja", "correct": true, "because": "Materialkosten variieren mit der Produktion"}, {"text": "Nein", "correct": false, "because": "Typisches Beispiel für variable Kosten"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind variable Kosten auch bei null Produktion vorhanden?', 2, '[{"text": "Ja", "correct": false, "because": "Bei null Produktion entstehen keine variablen Kosten"}, {"text": "Nein", "correct": true, "because": "Variable Kosten entstehen nur bei Produktion"}]'),
('00000000-0000-0000-0000-000000000000', 'Können variable Kosten in der Kostenrechnung ignoriert werden?', 2, '[{"text": "Ja", "correct": false, "because": "Sie sind essenziell für die Kalkulation"}, {"text": "Nein", "correct": true, "because": "Wichtig für genaue Kostenrechnung"}]');
INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Was sind variable Kosten?', 2, '[{"text": "Kosten, die mit der Produktionsmenge variieren", "correct": true, "because": "Definition der variablen Kosten"}, {"text": "Kosten, die immer gleich bleiben", "correct": false, "because": "Das sind Fixkosten"}, {"text": "Kosten für Gebäude", "correct": false, "because": "Das sind Fixkosten"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches ist ein Beispiel für variable Kosten?', 3, '[{"text": "Rohmaterial für Produkte", "correct": true, "because": "Ändert sich mit der Menge"}, {"text": "Miete für das Betriebsgebäude", "correct": false, "because": "Fixkosten"}, {"text": "Gehalt des Geschäftsführers", "correct": false, "because": "Fixkosten"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie verhalten sich variable Kosten bei steigender Produktion?', 2, '[{"text": "Sie steigen proportional", "correct": true, "because": "Mengenabhängigkeit"}, {"text": "Sie bleiben konstant", "correct": false, "because": "Das gilt für Fixkosten"}, {"text": "Sie sinken", "correct": false, "because": "Widerspricht der Definition"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Rolle spielen variable Kosten in der Kostenrechnung?', 3, '[{"text": "Sie dienen der Kalkulation der Stückkosten", "correct": true, "because": "Wichtig für Preisgestaltung"}, {"text": "Sie werden nur für Fixkosten genutzt", "correct": false, "because": "Falsche Zuordnung"}, {"text": "Sie sind irrelevant", "correct": false, "because": "Essenziell für Analyse"}]'),
('00000000-0000-0000-0000-000000000000', 'Was passiert mit variablen Kosten bei Produktionsstopp?', 2, '[{"text": "Sie fallen auf null", "correct": true, "because": "Keine Produktion, keine Kosten"}, {"text": "Sie bleiben gleich", "correct": false, "because": "Das gilt für Fixkosten"}, {"text": "Sie steigen an", "correct": false, "because": "Widerspricht der Definition"}]');
INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Welche Kosten zählen zu den variablen Kosten?', 4, '[{"text": "Rohstoffe", "correct": true, "because": "Mengenabhängig"}, {"text": "Strom für Produktion", "correct": true, "because": "Variiert mit Produktion"}, {"text": "Miete", "correct": false, "because": "Fixkosten"}, {"text": "Löhne für Akkordarbeit", "correct": true, "because": "Produktionsabhängig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Eigenschaften haben variable Kosten?', 3, '[{"text": "Sie ändern sich mit der Produktionsmenge", "correct": true, "because": "Definition"}, {"text": "Sie entstehen nur bei Produktion", "correct": true, "because": "Mengenabhängigkeit"}, {"text": "Sie sind unabhängig von der Produktion", "correct": false, "because": "Das sind Fixkosten"}, {"text": "Sie steigen proportional zur Auslastung", "correct": true, "because": "Typisches Verhalten"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Auswirkungen haben variable Kosten auf ein Unternehmen?', 4, '[{"text": "Sie beeinflussen die Stückkosten", "correct": true, "because": "Direkter Zusammenhang"}, {"text": "Sie sinken bei weniger Produktion", "correct": true, "because": "Mengenabhängig"}, {"text": "Sie bleiben bei Stillstand gleich", "correct": false, "because": "Sie fallen weg"}, {"text": "Sie sind relevant für Preiskalkulation", "correct": true, "because": "Wichtig für Gewinn"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Beispiele gehören nicht zu variablen Kosten?', 3, '[{"text": "Gehalt des Büropersonals", "correct": true, "because": "Fixkosten"}, {"text": "Materialkosten", "correct": false, "because": "Variable Kosten"}, {"text": "Abschreibungen auf Maschinen", "correct": true, "because": "Fixkosten"}, {"text": "Verpackungsmaterial", "correct": false, "because": "Variable Kosten"}]'),
('00000000-0000-0000-0000-000000000000', 'Warum sind variable Kosten in der Kostenrechnung wichtig?', 3, '[{"text": "Sie helfen bei der Preisgestaltung", "correct": true, "because": "Stückkostenberechnung"}, {"text": "Sie zeigen die Produktionsabhängigkeit", "correct": true, "because": "Mengenbezug"}, {"text": "Sie sind immer gleich", "correct": false, "because": "Das sind Fixkosten"}, {"text": "Sie beeinflussen die Gewinnmarge", "correct": true, "because": "Kostenstruktur"}]');
INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen richtig? a) Variable Kosten steigen mit der Produktion. b) Sie sind bei null Produktion vorhanden.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "a) richtig, b) falsch (keine Produktion, keine Kosten)"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Materialkosten sind variable Kosten. b) Miete gehört zu den variablen Kosten.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "a) richtig, b) falsch (Fixkosten)"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Variable Kosten beeinflussen die Stückkosten. b) Sie sind für langfristige Planung irrelevant.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "a) richtig, b) falsch (wichtig für Kalkulation)"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen korrekt? a) Variable Kosten fallen bei Produktionsstopp weg. b) Sie steigen bei mehr Produktion.', 3, '[{"text": "Nur a) stimmt", "correct": false, "because": "Beides ist richtig"}, {"text": "Beides stimmt", "correct": true, "because": "a) und b) entsprechen der Definition"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "Beides ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Strom für Maschinen ist eine variable Kostenart. b) Variable Kosten sind immer gleich hoch.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "a) richtig, b) falsch (mengenabhängig)"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]');